"""Fixed user-facing safety messages. Never generated by a model, never rewritten.

DRAFT: the wording below needs review by someone qualified (for example a
mental-health professional and the data protection lead) before launch.
"""

CRISIS_MESSAGE_VERSION = "2-draft"


def crisis_message(country: str | None) -> str:
    """The fixed crisis message for the user's country; a multi-country one when it is not known."""
    from app.modules.regions.crisis import crisis_message as build

    return build(country)


# What a user sees before they have said which country they are in.
CRISIS_MESSAGE = crisis_message(None)

_REFUSALS = {
    "live_interview_assistance": (
        "I can't help with getting answers during a real interview or assessment, because that "
        "would mislead the people assessing you. I can help you prepare properly: we can run "
        "mock interviews, practise explaining your past work out loud, and work through the "
        "questions you expect. Want to start with one?"
    ),
    "fake_credentials": (
        "I can't help invent or exaggerate references, qualifications or work history. That "
        "tends to unravel at the worst moment. I can help you present what you really have "
        "as strongly as possible, and plan how to close any gap honestly. Shall we start with "
        "what you've done?"
    ),
    "deception": (
        "I can't help with misleading an employer, interviewer or recruiter. If there's a "
        "difficult conversation behind this, I can help you plan how to say it honestly and "
        "clearly. What are you trying to achieve?"
    ),
    "other": (
        "I can't help with that one, because it involves deceiving someone or impersonating "
        "a real person. If you tell me what you're trying to achieve, I can suggest a "
        "straightforward way to get there."
    ),
}


def refusal_message(reason: str) -> str:
    return _REFUSALS.get(reason, _REFUSALS["other"])
